<div class="hud"><div class="k"><small>KILLS</small><b data-k>0</b></div><div class="t"><small>${M?"RANK":"TIME"}</small><b data-t>3:00</b></div><div class="hp"><small>ARMOR</small><i><u data-hp></u></i></div><div class="st"><small>STREAK</small><b data-st>0</b></div><div class="tm"><small>TEAM</small><b data-tm>0</b></div><div class="lead"><small>LEADER</small><b data-lead>\u2014</b></div></div>
